window.handleAdminRor = async function(reqId, action, targetUsername = "") {
  const amountInput = document.getElementById(`ror_amount_${reqId}`);
  const noteInput = document.getElementById(`ror_note_${reqId}`);
  let finalAmount = parseInt(amountInput ? amountInput.value : '0', 10);
  const customNote = noteInput ? noteInput.value.trim() : '';
  
  if (action === 'granted') {
    if (!finalAmount || finalAmount <= 0) {
      alert("Please enter a valid positive amount of coins.");
      return;
    }
    if (finalAmount > 20000) {
      alert("Maximum approval limit is 20,000 coins.");
      if (amountInput) amountInput.value = 20000;
      return;
    }
  }
  
  const displayName = targetUsername || 'this player';
  const confirmMsg = action === 'granted'
    ? `Approve ${finalAmount.toLocaleString()} 🪙 to ${displayName}?`
    : `Decline the coin claim from ${displayName}?`;
    
  if (!confirm(confirmMsg)) return;
  
  const cardEl = amountInput ? amountInput.closest('.admin-ror-card') : (noteInput ? noteInput.closest('.admin-ror-card') : null);
  const btns = cardEl ? cardEl.querySelectorAll('button') : [];
  if (amountInput) amountInput.disabled = true;
  if (noteInput) noteInput.disabled = true;
  btns.forEach(b => { b.disabled = true; b.textContent = "⏳..."; });
  
  try {
    await window.adminUpdateRorRequest(reqId, action, finalAmount, customNote);
  } catch(e) {
    console.error(e);
    alert("Error updating request: " + (e.message || e));
    if (amountInput) amountInput.disabled = false;
    if (noteInput) noteInput.disabled = false;
    btns.forEach(b => {
      b.disabled = false;
      b.textContent = b.classList.contains('btn-red') || b.textContent.includes('Decline') ? 'Decline' : 'Approve';
    });
  }
};

// ═══════════════════════════════════════════════════════════
// PLAYER ROR SUBVIEW CONTROLLERS & MY REQUESTS
// ═══════════════════════════════════════════════════════════
window._rorCurrentSubView = 'new';
window._myRorRequestsCache = null;
window._myRorRequestsCacheTime = 0;

window.switchRorSubView = function(view, btnEl) {
  window._rorCurrentSubView = view;
  const newBtn = document.getElementById('rorViewNewBtn');
  const myBtn = document.getElementById('rorViewMyBtn');
  const newSec = document.getElementById('rorNewRequestSection');
  const mySec = document.getElementById('rorMyRequestsSection');

  if (newBtn) newBtn.classList.toggle('active', view === 'new');
  if (myBtn) myBtn.classList.toggle('active', view === 'my');
  if (newSec) newSec.style.display = view === 'new' ? 'flex' : 'none';
  if (mySec) mySec.style.display = view === 'my' ? 'block' : 'none';

  if (view === 'my') {
    window.fetchMyRorRequests();
  }
};

window.fetchMyRorRequests = async function(forceRefresh = false) {
  const container = document.getElementById('rorMyRequestsList');
  if (!container) return;

  const identity = (typeof window.getRorPlayerIdentity === "function") 
    ? window.getRorPlayerIdentity() 
    : { playerId: window._currentPlayerId || "", username: window._currentUsername || "" };

  if (!identity.playerId) {
    container.innerHTML = `
      <div style="text-align:center; color:var(--text-muted); padding:40px 20px; background: var(--surface-card); border-radius: var(--radius-lg); border: 1px solid var(--border-card); font-family: var(--font-body);">
        ⚠️ You must be logged in to view your submission history.
        <div style="margin-top:12px;">
          <button type="button" class="btn" style="padding:8px 18px; font-size:0.85rem; background:var(--gold); color:#07041a; font-weight:700; border-radius:999px; cursor:pointer;" onclick="if(window.showLobby) window.showLobby(); if(window.toggleLobbyTab) window.toggleLobbyTab('login');">Log In to Account</button>
        </div>
      </div>
    `;
    return;
  }

  const now = Date.now();
  if (!forceRefresh && window._myRorRequestsCache && (now - window._myRorRequestsCacheTime < 30000)) {
    window.renderMyRorRequests(window._myRorRequestsCache);
    return;
  }

  container.innerHTML = `
    <div style="text-align:center; color:var(--text-muted); padding:40px 20px; background: var(--surface-card); border-radius: var(--radius-lg); border: 1px solid var(--border-card); font-family: var(--font-body);">
      ⏳ Loading your requests…
    </div>
  `;

  try {
    if (typeof window.getMyRorRequests !== 'function') {
      throw new Error("Service initializing. Please wait a moment.");
    }
    const list = await window.getMyRorRequests(identity.playerId);
    window._myRorRequestsCache = list;
    window._myRorRequestsCacheTime = Date.now();
    window.renderMyRorRequests(list);

    // Update pending count pill in subnav
    const pendingCount = list.filter(r => r.status === 'pending').length;
    const pill = document.getElementById('rorMyReqCountPill');
    if (pill) {
      if (pendingCount > 0) {
        pill.textContent = pendingCount;
        pill.style.display = 'inline-flex';
      } else {
        pill.style.display = 'none';
      }
    }
  } catch (e) {
    console.error("fetchMyRorRequests error:", e);
    container.innerHTML = `
      <div style="text-align:center; color:#ef4444; padding:30px 16px; background:var(--surface-card); border-radius:var(--radius-lg); border:1px solid rgba(239, 68, 68, 0.3); font-family:var(--font-body);">
        Error loading requests: ${escapeHtml(e.message || String(e))}
      </div>
    `;
  }
};

window.renderMyRorRequests = function(requests) {
  const container = document.getElementById('rorMyRequestsList');
  const clearAllBtn = document.getElementById('rorClearAllBtn');
  if (!container) return;

  const now = Date.now();
  const ROR_PRUNE_MS = 3 * 24 * 60 * 60 * 1000;

  // Filter out any resolved (approved or declined) requests older than 3 days
  const activeRequests = (requests || []).filter(req => {
    const isResolved = req.status === 'granted' || req.status === 'processing_granted' ||
                       req.status === 'declined' || req.status === 'processing_declined';
    if (isResolved) {
      const resTime = Number(req.resolvedAt || req.timestamp || 0);
      if (resTime > 0 && (now - resTime) > ROR_PRUNE_MS) return false;
    }
    return true;
  });

  const hasResolved = activeRequests.some(r =>
    r.status === 'granted' || r.status === 'processing_granted' ||
    r.status === 'declined' || r.status === 'processing_declined'
  );
  if (clearAllBtn) {
    clearAllBtn.style.display = hasResolved ? 'inline-flex' : 'none';
  }

  if (activeRequests.length === 0) {
    container.innerHTML = `
      <div style="text-align:center; color:var(--text-muted); padding:40px 20px; background: var(--surface-card); border-radius: var(--radius-lg); border: 1px solid var(--border-card); font-family: var(--font-body);">
        No requests submitted yet.<br>
        <span style="font-size:0.82rem; color:rgba(255,255,255,0.4); margin-top:6px; display:inline-block;">Tap <strong>✨ New Request</strong> above to submit your regatta or task claim!</span>
      </div>
    `;
    return;
  }

  let html = '';
  activeRequests.forEach(req => {
    const isApproved = req.status === 'granted' || req.status === 'processing_granted';
    const isDeclined = req.status === 'declined' || req.status === 'processing_declined';
    const isResolved = isApproved || isDeclined;

    let statusBadge = '';
    if (req.status === 'pending') {
      statusBadge = `<span style="background: rgba(245, 197, 66, 0.15); border: 1px solid var(--border-gold); padding: 4px 10px; border-radius: var(--radius-pill); font-family: var(--font-display); font-size: 0.78rem; font-weight: 700; color: var(--gold); white-space: nowrap;">⏳ Pending Approval</span>`;
    } else if (isApproved) {
      const grantedAmt = (typeof req.grantedCoins === 'number' && req.grantedCoins > 0) ? req.grantedCoins : req.requestedCoins;
      statusBadge = `<span style="background: rgba(52, 211, 153, 0.15); border: 1px solid rgba(52, 211, 153, 0.4); padding: 4px 10px; border-radius: var(--radius-pill); font-family: var(--font-display); font-size: 0.78rem; font-weight: 700; color: #34d399; white-space: nowrap;">✅ Grant Approved (+${(grantedAmt || 0).toLocaleString()} 🪙)</span>`;
    } else if (isDeclined) {
      statusBadge = `<span style="background: rgba(239, 68, 68, 0.15); border: 1px solid rgba(239, 68, 68, 0.4); padding: 4px 10px; border-radius: var(--radius-pill); font-family: var(--font-display); font-size: 0.78rem; font-weight: 700; color: #ef4444; white-space: nowrap;">❌ Declined</span>`;
    } else {
      statusBadge = `<span style="background: rgba(255,255,255,0.1); border: 1px solid rgba(255,255,255,0.2); padding: 4px 10px; border-radius: var(--radius-pill); font-family: var(--font-display); font-size: 0.78rem; font-weight: 700; color: var(--text-muted); white-space: nowrap;">${escapeHtml(req.status || 'Unknown')}</span>`;
    }

    const hasProofNotice = Array.isArray(req.imageUrls) && req.imageUrls.length > 0;
    const noteText = req.adminCustomNote || (isApproved ? req.grantNote : '');

    const borderStyle = isApproved 
      ? 'border: 1px solid rgba(52, 211, 153, 0.35); box-shadow: 0 4px 18px rgba(0,0,0,0.4), 0 0 14px rgba(52, 211, 153, 0.12);' 
      : (isDeclined 
        ? 'border: 1px solid rgba(239, 68, 68, 0.35); box-shadow: 0 4px 18px rgba(0,0,0,0.4), 0 0 14px rgba(239, 68, 68, 0.1);' 
        : 'border: 1px solid rgba(245, 197, 66, 0.3); box-shadow: 0 4px 18px rgba(0,0,0,0.4), 0 0 14px rgba(245, 197, 66, 0.1);');

    html += `
      <div class="ror-my-card" style="background: rgba(24, 19, 48, 0.88); border-radius: 16px; padding: 15px; display: flex; flex-direction: column; gap: 10px; ${borderStyle}">
        <div style="display: flex; justify-content: space-between; align-items: flex-start; gap: 8px;">
          <div>
            <div style="font-weight: 800; font-family: var(--font-display); font-size: 1.15rem; color: var(--gold); display: flex; align-items: center; gap: 4px;">
              <span>🪙</span> <span>${req.requestedCoins ? req.requestedCoins.toLocaleString() : 0}</span>
            </div>
            <div style="font-size: 0.74rem; color: var(--text-muted); margin-top: 2px;">
              ${new Date(req.timestamp || Date.now()).toLocaleString()}
            </div>
          </div>
          <div style="display: flex; flex-direction: column; align-items: flex-end; gap: 6px;">
            ${statusBadge}
          </div>
        </div>

        ${req.description ? `
          <div style="background: #0e0a1e; padding: 10px 12px; border-radius: 12px; font-size: 0.88rem; color: var(--text-secondary); line-height: 1.45; border: 1px solid rgba(255,255,255,0.06); font-family: var(--font-body); display: flex; gap: 6px; align-items: flex-start;">
            <span style="color: var(--gold); font-size: 0.95rem;">💬</span>
            <div style="flex: 1;">${escapeHtml(req.description)}</div>
          </div>
        ` : ''}

        ${noteText ? `
          <div style="background: rgba(167, 139, 250, 0.09); border: 1px solid rgba(167, 139, 250, 0.28); padding: 8px 12px; border-radius: 12px; font-size: 0.82rem; color: #c4b5fd; line-height: 1.4; font-family: var(--font-body);">
            <strong style="color: #ddd6fe; font-family: var(--font-display);">📝 Admin Note:</strong> ${escapeHtml(noteText)}
          </div>
        ` : ''}

        ${hasProofNotice ? `
          <div style="font-size: 0.74rem; color: var(--text-muted); font-style: italic; display: flex; align-items: center; gap: 4px;">
            <span>📸</span> <span>${req.imageUrls.length} proof screenshot(s) attached (preview hidden to save data)</span>
          </div>
        ` : ''}

        <div class="ror-my-card-actions" style="display: flex; gap: 8px; justify-content: flex-end; align-items: center; margin-top: 4px; padding-top: 10px; border-top: 1px solid rgba(255, 255, 255, 0.08); flex-wrap: wrap;">
          <button
            type="button"
            class="btn"
            style="min-height: 36px; padding: 6px 14px; font-size: 0.8rem; font-family: var(--font-display); font-weight: 600; border-radius: 999px; background: rgba(245, 197, 66, 0.12); border: 1px solid rgba(245, 197, 66, 0.35); color: var(--gold); cursor: pointer; display: inline-flex; align-items: center; gap: 5px; transition: all 0.15s;"
            onclick="openEditRorNote('${escapeHtml(req.id || '')}')"
            title="Edit your note for this request"
          >
            ✏️ Edit Note
          </button>
          <button
            type="button"
            class="btn"
            style="min-height: 36px; padding: 6px 14px; font-size: 0.8rem; font-family: var(--font-display); font-weight: 600; border-radius: 999px; background: rgba(239, 68, 68, 0.12); border: 1px solid rgba(239, 68, 68, 0.35); color: #f87171; cursor: pointer; display: inline-flex; align-items: center; gap: 5px; transition: all 0.15s;"
            onclick="deleteMyRorRequest('${escapeHtml(req.id || '')}')"
            title="Delete this request"
          >
            🗑️ Delete
          </button>
        </div>
      </div>
    `;
  });

  html += `
    <div style="text-align: center; font-size: 0.74rem; color: var(--text-muted); margin-top: 4px; padding: 6px 12px; font-family: var(--font-body);">
      ℹ️ Approved and declined requests are automatically pruned after 3 days.
    </div>
  `;

  container.innerHTML = html;
};

window.deleteMyRorRequest = async function(reqId) {
  if (!reqId) return;
  const list = window._myRorRequestsCache || [];
  const req = list.find(r => (r.id || '') === reqId);
  const isPending = !req || req.status === 'pending';
  const confirmMsg = isPending
    ? "Are you sure you want to cancel and delete this pending claim request?"
    : "Are you sure you want to delete this request from your history?";
  if (!confirm(confirmMsg)) return;

  try {
    if (typeof window.deleteRorRequest === 'function') {
      await window.deleteRorRequest(reqId);
    }
    if (Array.isArray(window._myRorRequestsCache)) {
      window._myRorRequestsCache = window._myRorRequestsCache.filter(r => (r.id || '') !== reqId);
      window.renderMyRorRequests(window._myRorRequestsCache);
    }
    const pendingCount = (window._myRorRequestsCache || []).filter(r => r.status === 'pending').length;
    const pill = document.getElementById('rorMyReqCountPill');
    if (pill) {
      if (pendingCount > 0) {
        pill.textContent = pendingCount;
        pill.style.display = 'inline-flex';
      } else {
        pill.style.display = 'none';
      }
    }
    if (typeof window.showToast === 'function') {
      window.showToast("🗑️ Request deleted");
    }
  } catch (e) {
    console.error("deleteMyRorRequest error:", e);
    if (typeof window.showToast === 'function') {
      window.showToast("❌ Failed to delete request: " + (e.message || e));
    }
  }
};
window.clearOneRorRequest = window.deleteMyRorRequest;

window._pendingEditRorReqId = null;

window.openEditRorNote = function(reqId) {
  if (!reqId) return;
  const list = window._myRorRequestsCache || [];
  const req = list.find(r => (r.id || '') === reqId);
  if (!req) return;

  window._pendingEditRorReqId = reqId;
  const input = document.getElementById('editRorNoteInput');
  const badge = document.getElementById('editRorNoteCoinBadge');
  const errEl = document.getElementById('editRorNoteError');
  const counter = document.getElementById('editRorCharCounter');

  if (badge) {
    const coins = (req.requestedCoins || 0).toLocaleString();
    badge.innerHTML = `🪙 ${coins} Coins Claim`;
  }
  if (input) {
    input.value = req.description || '';
  }
  if (counter && input) {
    counter.textContent = `${input.value.length} / 300`;
    counter.style.color = input.value.length > 280 ? '#ef4444' : 'var(--text-muted, #9a907b)';
  }
  if (errEl) {
    errEl.style.display = 'none';
  }

  if (typeof showOverlay === 'function') {
    showOverlay('overlayEditRorNote');
  } else {
    const el = document.getElementById('overlayEditRorNote');
    if (el) el.classList.add('show');
  }
  if (input) {
    setTimeout(() => input.focus(), 120);
  }
};

window.updateEditRorCharCount = function(el) {
  const counter = document.getElementById('editRorCharCounter');
  const errEl = document.getElementById('editRorNoteError');
  if (!counter || !el) return;
  const len = el.value.length;
  counter.textContent = `${len} / 300`;
  counter.style.color = len > 280 ? '#ef4444' : 'var(--text-muted, #9a907b)';
  if (len > 0 && errEl) {
    errEl.style.display = 'none';
  }
};

window.saveEditedRorNote = async function() {
  const reqId = window._pendingEditRorReqId;
  if (!reqId) return;
  const input = document.getElementById('editRorNoteInput');
  const errEl = document.getElementById('editRorNoteError');
  const btn = document.getElementById('saveEditRorNoteBtn');
  if (!input) return;

  const newNote = input.value.trim();
  if (!newNote) {
    if (errEl) {
      errEl.textContent = 'A purpose or task note is compulsory.';
      errEl.style.display = 'block';
    }
    input.focus();
    return;
  }

  if (btn) {
    btn.disabled = true;
    btn.textContent = '⏳ Saving…';
  }

  try {
    if (typeof window.updateRorRequestNote === 'function') {
      await window.updateRorRequestNote(reqId, newNote);
    } else {
      throw new Error("Update service not available. Please wait a moment.");
    }

    if (Array.isArray(window._myRorRequestsCache)) {
      const cached = window._myRorRequestsCache.find(r => (r.id || '') === reqId);
      if (cached) cached.description = newNote;
      window.renderMyRorRequests(window._myRorRequestsCache);
    }

    if (typeof closeOverlay === 'function') {
      closeOverlay('overlayEditRorNote');
    } else {
      const el = document.getElementById('overlayEditRorNote');
      if (el) el.classList.remove('show');
    }

    if (typeof window.showToast === 'function') {
      window.showToast("✅ Note updated successfully!");
    }
  } catch (e) {
    console.error("saveEditedRorNote error:", e);
    if (errEl) {
      errEl.textContent = 'Error: ' + (e.message || e);
      errEl.style.display = 'block';
    } else if (typeof window.showToast === 'function') {
      window.showToast("❌ Failed to update note: " + (e.message || e));
    }
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.textContent = '💾 Save Changes';
    }
  }
};

window.clearAllResolvedRorRequests = async function() {
  const cache = window._myRorRequestsCache || [];
  const resolved = cache.filter(r =>
    r.status === 'granted' || r.status === 'processing_granted' ||
    r.status === 'declined' || r.status === 'processing_declined'
  );
  if (resolved.length === 0) {
    if (typeof window.showToast === 'function') {
      window.showToast("No approved or declined requests to clear.");
    }
    return;
  }
  if (!confirm(`Clear all ${resolved.length} completed/declined request(s) from your history?`)) return;

  const btn = document.getElementById('rorClearAllBtn');
  if (btn) {
    btn.disabled = true;
    btn.textContent = "⏳ Clearing…";
  }

  try {
    const ids = resolved.map(r => r.id).filter(Boolean);
    const clearFn = window.clearResolvedRorRequests || window.clearApprovedRorRequests;
    if (typeof clearFn === 'function') {
      await clearFn(ids);
    }
    if (Array.isArray(window._myRorRequestsCache)) {
      const resolvedIds = new Set(ids);
      window._myRorRequestsCache = window._myRorRequestsCache.filter(r => !resolvedIds.has(r.id));
      window.renderMyRorRequests(window._myRorRequestsCache);
    }
    if (typeof window.showToast === 'function') {
      window.showToast("🧹 Completed and declined requests cleared!");
    }
  } catch (e) {
    console.error("clearAllResolvedRorRequests error:", e);
    if (typeof window.showToast === 'function') {
      window.showToast("❌ Failed to clear: " + (e.message || e));
    }
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.textContent = "🧹 Clear Done";
    }
  }
};
window.clearAllApprovedRorRequests = window.clearAllResolvedRorRequests;

// ═══════════════════════════════════════════════════════════
// 🔔 ADMIN BROADCAST NOTIFICATIONS & ANNOUNCEMENTS CONTROLLER
// ═══════════════════════════════════════════════════════════

let adminNotifSelectedFile = null;
window._unseenNotifQueue = [];
window._totalUnseenBatch = 0;
window._currentUnseenIdx = 0;
window._currentOverlayNotif = null;

function formatNotifTime(ts) {
  if (!ts) return "Recently";
  const now = Date.now();
  const diff = now - ts;
  if (diff < 60000) return "Just now";
  if (diff < 3600000) return Math.floor(diff / 60000) + "m ago";
  if (diff < 86400000) return Math.floor(diff / 3600000) + "h ago";
  if (diff < 604800000) return Math.floor(diff / 86400000) + "d ago";
  return new Date(ts).toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric"
  });
}

function getSeenNotifIds() {
  const pid = window._currentPlayerId || (typeof profile === "object" && profile && profile.playerId) || "guest";
  const seenSet = new Set();

  if (Array.isArray(window._cachedSeenNotifications)) {
    window._cachedSeenNotifications.forEach(id => id && seenSet.add(id));
  }
  if (Array.isArray(window._cloudSeenNotifs)) {
    window._cloudSeenNotifs.forEach(id => id && seenSet.add(id));
  }
  if (typeof profile === "object" && profile && Array.isArray(profile.seenNotifications)) {
    profile.seenNotifications.forEach(id => id && seenSet.add(id));
  }

  try {
    const raw = localStorage.getItem("da_seen_notifications_" + pid);
    if (raw) {
      const arr = JSON.parse(raw);
      if (Array.isArray(arr)) arr.forEach(id => id && seenSet.add(id));
    }
  } catch (e) {}

  if (pid !== "guest") {
    try {
      const guestRaw = localStorage.getItem("da_seen_notifications_guest");
      if (guestRaw) {
        const arr = JSON.parse(guestRaw);
        if (Array.isArray(arr)) arr.forEach(id => id && seenSet.add(id));
      }
    } catch (e) {}
  }

  try {
    const sessRaw = sessionStorage.getItem("da_seen_notifications_" + pid);
    if (sessRaw) {
      const arr = JSON.parse(sessRaw);
      if (Array.isArray(arr)) arr.forEach(id => id && seenSet.add(id));
    }
  } catch (e) {}

  return Array.from(seenSet);
}
window.getSeenNotifIds = getSeenNotifIds;

function markNotifAsSeen(notifId) {
  if (!notifId) return;
  const pid = window._currentPlayerId || (typeof profile === "object" && profile && profile.playerId) || "guest";

  if (!window._cachedSeenNotifications) window._cachedSeenNotifications = [];
  if (!window._cachedSeenNotifications.includes(notifId)) {
    window._cachedSeenNotifications.push(notifId);
  }

  try {
    const raw = localStorage.getItem("da_seen_notifications_" + pid);
    const seen = raw ? JSON.parse(raw) : [];
    if (!seen.includes(notifId)) {
      seen.push(notifId);
      localStorage.setItem("da_seen_notifications_" + pid, JSON.stringify(seen));
    }
    const gRaw = localStorage.getItem("da_seen_notifications_guest");
    const gSeen = gRaw ? JSON.parse(gRaw) : [];
    if (!gSeen.includes(notifId)) {
      gSeen.push(notifId);
      localStorage.setItem("da_seen_notifications_guest", JSON.stringify(gSeen));
    }
  } catch (e) {}

  try {
    const sRaw = sessionStorage.getItem("da_seen_notifications_" + pid);
    const sSeen = sRaw ? JSON.parse(sRaw) : [];
    if (!sSeen.includes(notifId)) {
      sSeen.push(notifId);
      sessionStorage.setItem("da_seen_notifications_" + pid, JSON.stringify(sSeen));
    }
  } catch (e) {}

  if (typeof profile === "object" && profile) {
    if (!Array.isArray(profile.seenNotifications)) profile.seenNotifications = [];
    if (!profile.seenNotifications.includes(notifId)) profile.seenNotifications.push(notifId);
  }

  // Atomically persist seen notification in Firestore so it never repeats across logins or devices
  if (typeof window.recordNotificationSeen === "function") {
    window.recordNotificationSeen(notifId);
  }

  updateNotificationsBadge();
}
window.markNotifAsSeen = markNotifAsSeen;

function updateNotificationsBadge() {
  const badge = document.getElementById("notifBellBadge");
  if (!badge) return;
  const list = window._adminNotifications || [];
  const totalCount = Array.isArray(list) ? list.length : 0;

  // The number of notifications currently present on the website is fixed on the notification icon
  if (totalCount > 0) {
    badge.style.display = "flex";
    badge.textContent = totalCount > 99 ? "99+" : String(totalCount);
  } else {
    badge.style.display = "none";
    badge.textContent = "0";
  }

  // Also sync the notification count badge in the notifications modal header
  const headerBadge = document.getElementById("notifListCountBadge");
  if (headerBadge) {
    headerBadge.textContent = totalCount === 1 ? "1 Announcement" : `${totalCount} Announcements`;
  }
}
window.updateNotificationsBadge = updateNotificationsBadge;

window.checkUnseenNotifications = function() {
  // If magic door hasn't finished opening or lobby is visible, wait
  if (!window._doorOpened) return;
  const lobby = document.getElementById("lobbyScreen");
  if (lobby && lobby.style.display !== "none") return;

  const overlay = document.getElementById("overlayNotificationAnnouncement");
  if (overlay && overlay.style.display === "flex") return; // already showing

  const list = window._adminNotifications || [];
  if (!list.length) return;

  const seen = getSeenNotifIds();
  // Filter only unseen notifications
  const unseen = list.filter(n => n && n.id && !seen.includes(n.id));
  if (!unseen.length) {
    updateNotificationsBadge();
    return;
  }

  // Sort chronologically (oldest to newest) so player reads in sequential order
  unseen.sort((a, b) => (a.timestamp || 0) - (b.timestamp || 0));

  window._unseenNotifQueue = unseen;
  window._totalUnseenBatch = unseen.length;
  window._currentUnseenIdx = 0;

  showNextNotificationInQueue();
};

function getNotificationAdminPhoto(notif) {
  if (!notif) return "";
  if (notif.adminPhoto && typeof notif.adminPhoto === "string" && notif.adminPhoto.trim()) {
    return notif.adminPhoto.trim();
  }
  const pid = notif.adminPid || "";
  const name = (notif.adminName || "").toLowerCase().trim();
  const currentPid = (typeof _currentPlayerId !== "undefined" && _currentPlayerId) || window._currentPlayerId || (typeof profile === "object" && profile && profile.playerId) || "";
  const myName = (typeof profile === "object" && profile && profile.name) ? String(profile.name).trim().toLowerCase() : "";

  if (typeof profile === "object" && profile && profile.photoURL) {
    if ((pid && currentPid && pid === currentPid) || (name && myName && name === myName)) {
      return profile.photoURL;
    }
  }
  if (pid && window._playerPhotoMap && window._playerPhotoMap[pid]) {
    return window._playerPhotoMap[pid];
  }
  if (name && window._playerPhotoByNameMap && window._playerPhotoByNameMap[name]) {
    return window._playerPhotoByNameMap[name];
  }
  if (window._cachedCommunityMembers && Array.isArray(window._cachedCommunityMembers)) {
    const mem = window._cachedCommunityMembers.find(m => m && ((pid && (m.playerId === pid || m.id === pid)) || (name && m.name && m.name.toLowerCase() === name)));
    if (mem && mem.photoURL) return mem.photoURL;
  }
  if (window._adminPlayersCache && Array.isArray(window._adminPlayersCache.players)) {
    const p = window._adminPlayersCache.players.find(x => x && ((pid && (x.id === pid || x.playerId === pid)) || (name && x.name && x.name.toLowerCase() === name)));
    if (p && p.photoURL) return p.photoURL;
  }
  return "";
}
window.getNotificationAdminPhoto = getNotificationAdminPhoto;

function showNextNotificationInQueue() {
  if (!window._unseenNotifQueue || window._unseenNotifQueue.length === 0) {
    const overlay = document.getElementById("overlayNotificationAnnouncement");
    if (overlay) overlay.style.display = "none";
    window._currentOverlayNotif = null;
    updateNotificationsBadge();
    return;
  }

  const notif = window._unseenNotifQueue.shift();
  window._currentOverlayNotif = notif;
  window._currentUnseenIdx = (window._currentUnseenIdx || 0) + 1;

  // Immediately mark as seen as soon as presented to ensure it only comes ONCE after login
  if (notif && notif.id) {
    markNotifAsSeen(notif.id);
  }

  const overlay = document.getElementById("overlayNotificationAnnouncement");
  if (!overlay) return;

  // 1. Admin Avatar / Photo
  const photoEl = document.getElementById("notifOverlaySenderPhoto");
  const emojiEl = document.getElementById("notifOverlaySenderEmoji");
  const adminPhoto = getNotificationAdminPhoto(notif);

  if (adminPhoto) {
    if (photoEl) {
      photoEl.src = adminPhoto;
      photoEl.style.display = "block";
      photoEl.onerror = function() {
        this.style.display = "none";
        if (emojiEl) {
          emojiEl.textContent = notif.adminAvatar || "👑";
          emojiEl.style.display = "block";
        }
      };
    }
    if (emojiEl) emojiEl.style.display = "none";
  } else {
    if (photoEl) photoEl.style.display = "none";
    if (emojiEl) {
      emojiEl.textContent = notif.adminAvatar || "👑";
      emojiEl.style.display = "block";
    }
  }

  // 2. Admin Name & Role
  const nameEl = document.getElementById("notifOverlaySenderName");
  if (nameEl) nameEl.textContent = notif.adminName || "Admin";

  const timeEl = document.getElementById("notifOverlayTime");
  if (timeEl) timeEl.textContent = formatNotifTime(notif.timestamp);

  // 3. Queue Badge / Step Indicator
  const badgeEl = document.getElementById("notifOverlayQueueBadge");
  const actionBtn = document.getElementById("notifOverlayActionBtn");
  if (window._totalUnseenBatch > 1) {
    if (badgeEl) {
      badgeEl.style.display = "inline-block";
      badgeEl.textContent = `${window._currentUnseenIdx} of ${window._totalUnseenBatch}`;
    }
    if (actionBtn) {
      actionBtn.innerHTML = `<span>Next Announcement ➔ (${window._currentUnseenIdx}/${window._totalUnseenBatch})</span>`;
    }
  } else {
    if (badgeEl) badgeEl.style.display = "none";
    if (actionBtn) {
      actionBtn.innerHTML = `<span>Close &amp; Save to Notifications 🔔</span>`;
    }
  }

  // 4. Full Image Uploaded by Admin (Shown First)
  const imgWrap = document.getElementById("notifOverlayImageWrap");
  const imgEl = document.getElementById("notifOverlayImage");
  if (notif.imageUrl) {
    if (imgEl) imgEl.src = notif.imageUrl;
    if (imgWrap) imgWrap.style.display = "block";
  } else {
    if (imgWrap) imgWrap.style.display = "none";
    if (imgEl) imgEl.src = "";
  }

  // 5. Message Sent by Admin (No character limit)
  const msgEl = document.getElementById("notifOverlayMessage");
  if (msgEl) {
    msgEl.innerHTML = escapeHtml(notif.message || "").replace(/\n/g, "<br>");
  }

  overlay.style.display = "flex";
}
window.showNextNotificationInQueue = showNextNotificationInQueue;

window.closeNotificationOverlay = function() {
  if (window._currentOverlayNotif && window._currentOverlayNotif.id) {
    markNotifAsSeen(window._currentOverlayNotif.id);
  }

  // If there are more notifications queued up, show them one by one
  if (window._unseenNotifQueue && window._unseenNotifQueue.length > 0) {
    showNextNotificationInQueue();
    return;
  }

  // All unseen notifications have been viewed
  window._currentOverlayNotif = null;
  const overlay = document.getElementById("overlayNotificationAnnouncement");
  if (overlay) overlay.style.display = "none";

  // Pulse top-right bell button to indicate saved to notifications section
  const bell = document.getElementById("notifBellBtn");
  if (bell) {
    bell.style.boxShadow = "0 0 20px #f5c542, 0 0 35px rgba(245, 197, 66, 0.6)";
    bell.style.borderColor = "#f5c542";
    setTimeout(() => {
      bell.style.boxShadow = "";
      bell.style.borderColor = "rgba(240, 192, 48, 0.4)";
    }, 2800);
  }

  if (typeof showToast === "function") {
    showToast("🔔 Announcement saved in top-right notifications.");
  }

  updateNotificationsBadge();
};

window.handleNotifBackdropClick = function(e) {
  if (e && e.target && e.target.id === "overlayNotificationAnnouncement") {
    window.closeNotificationOverlay();
  }
};

window.openNotificationsModal = function() {
  renderNotificationsModalList();
  const modal = document.getElementById("overlayNotificationsList");
  if (modal) modal.style.display = "flex";
  updateNotificationsBadge();
};

window.closeNotificationsModal = function() {
  const modal = document.getElementById("overlayNotificationsList");
  if (modal) modal.style.display = "none";
  updateNotificationsBadge();
};

window.handleNotifListBackdropClick = function(e) {
  if (e && e.target && e.target.id === "overlayNotificationsList") {
    window.closeNotificationsModal();
  }
};

function renderNotificationsModalList() {
  const container = document.getElementById("notifListItemsContainer");
  if (!container) return;

  const list = window._adminNotifications || [];
  const headerBadge = document.getElementById("notifListCountBadge");
  if (headerBadge) {
    headerBadge.textContent = list.length === 1 ? "1 Announcement" : `${list.length} Announcements`;
  }
  if (!list.length) {
    container.innerHTML = `
      <div class="notif-empty-state">
        <span style="font-size: 2.5rem; margin-bottom: 8px;">📭</span>
        <div style="font-family: var(--font-display); font-weight: 700; font-size: 1.05rem; color: var(--gold);">No announcements yet</div>
        <p style="font-size: 0.84rem; color: var(--text-muted); margin-top: 4px; max-width: 280px;">When admins publish team updates or notices, they will appear here.</p>
      </div>
    `;
    return;
  }

  let html = "";
  list.forEach(notif => {
    const adminPhoto = getNotificationAdminPhoto(notif);
    const safeAvatar = escapeHtml(notif.adminAvatar || "👑").replace(/'/g, "\\'");
    const avatarContent = adminPhoto
      ? `<img src="${escapeHtml(adminPhoto)}" alt="Admin" style="width:100%;height:100%;object-fit:cover;border-radius:50%;display:block;" onerror="this.outerHTML='<span>${safeAvatar}</span>'">`
      : `<span>${escapeHtml(notif.adminAvatar || "👑")}</span>`;

    const imgBlock = notif.imageUrl
      ? `<div class="notif-card-image-wrap">
           <img src="${escapeHtml(notif.imageUrl)}" alt="Announcement Image" class="notif-card-image" loading="lazy" />
         </div>`
      : "";

    html += `
      <div class="notif-card-item">
        <div class="notif-card-header">
          <div class="notif-card-author">
            <div class="notif-card-avatar">${avatarContent}</div>
            <div>
              <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;">
                <span class="notif-card-name">${escapeHtml(notif.adminName || "Admin")}</span>
                <span class="notif-role-tag">Mantralay</span>
              </div>
              <div class="notif-card-date">${formatNotifTime(notif.timestamp)}</div>
            </div>
          </div>
        </div>
        ${imgBlock}
        <div class="notif-card-message">${escapeHtml(notif.message || "").replace(/\n/g, "<br>")}</div>
      </div>
    `;
  });

  container.innerHTML = html;
}

// ── Admin Panel Compose & Delete Handlers ──
window.handleAdminNotifFileSelected = function(input) {
  const alertEl = document.getElementById("adminNotifAlertMsg");
  if (alertEl) alertEl.style.display = "none";

  if (!input || !input.files || !input.files[0]) return;
  const file = input.files[0];

  if (file.size > 20 * 1024 * 1024) {
    if (alertEl) {
      alertEl.style.display = "block";
      alertEl.style.background = "rgba(239, 68, 68, 0.15)";
      alertEl.style.border = "1px solid rgba(239, 68, 68, 0.4)";
      alertEl.style.color = "#fca5a5";
      alertEl.textContent = `⚠️ File "${file.name}" exceeds the 20 MB limit. Please select a smaller image.`;
    }
    input.value = "";
    return;
  }

  adminNotifSelectedFile = file;
  const wrap = document.getElementById("adminNotifPreviewWrap");
  const previewImg = document.getElementById("adminNotifPreviewImg");
  const dropText = document.getElementById("adminNotifDropzoneText");

  if (previewImg) {
    try {
      previewImg.src = URL.createObjectURL(file);
    } catch(e) {}
  }
  if (wrap) wrap.style.display = "block";
  if (dropText) dropText.textContent = `Attached: ${file.name} (Tap to change)`;
};

window.clearAdminNotifFile = function() {
  adminNotifSelectedFile = null;
  const input = document.getElementById("adminNotifFileInput");
  if (input) input.value = "";
  const wrap = document.getElementById("adminNotifPreviewWrap");
  if (wrap) wrap.style.display = "none";
  const previewImg = document.getElementById("adminNotifPreviewImg");
  if (previewImg) previewImg.src = "";
  const dropText = document.getElementById("adminNotifDropzoneText");
  if (dropText) dropText.textContent = "Tap to attach photo/poster";
  const alertEl = document.getElementById("adminNotifAlertMsg");
  if (alertEl) alertEl.style.display = "none";
};

window.publishAdminNotificationUI = async function() {
  const msgInput = document.getElementById("adminNotifMsgInput");
  const btn = document.getElementById("adminNotifSendBtn");
  const statusEl = document.getElementById("adminNotifUploadStatus");
  const alertEl = document.getElementById("adminNotifAlertMsg");

  if (alertEl) alertEl.style.display = "none";

  const message = (msgInput ? msgInput.value : "").trim();
  if (!message && !adminNotifSelectedFile) {
    if (alertEl) {
      alertEl.style.display = "block";
      alertEl.style.background = "rgba(239, 68, 68, 0.15)";
      alertEl.style.border = "1px solid rgba(239, 68, 68, 0.4)";
      alertEl.style.color = "#fca5a5";
      alertEl.textContent = "⚠️ Please write an announcement message or attach an image.";
    }
    return;
  }

  if (btn) btn.disabled = true;
  if (statusEl) {
    statusEl.style.display = "block";
    statusEl.textContent = "⏳ Preparing announcement...";
  }

  try {
    if (typeof window.publishAdminNotification !== "function") {
      throw new Error("Publish notification service is not available.");
    }

    const adminInfo = {
      name: (typeof profile === "object" && profile && profile.name) || (typeof window._currentUsername === "string" && window._currentUsername) || "",
      pid: window._currentPlayerId || (typeof profile === "object" && profile && profile.playerId) || "",
      photo: (typeof profile === "object" && profile && profile.photoURL) || "",
      avatar: (typeof profile === "object" && profile && profile.avatar) || "👑"
    };
    if (!adminInfo.photo && adminInfo.pid && window._playerPhotoMap && window._playerPhotoMap[adminInfo.pid]) {
      adminInfo.photo = window._playerPhotoMap[adminInfo.pid];
    }
    if (!adminInfo.photo && adminInfo.name && window._playerPhotoByNameMap && window._playerPhotoByNameMap[adminInfo.name.toLowerCase()]) {
      adminInfo.photo = window._playerPhotoByNameMap[adminInfo.name.toLowerCase()];
    }

    await window.publishAdminNotification(message, adminNotifSelectedFile, (curr, total, step) => {
      if (statusEl) {
        if (step === "optimizing") statusEl.textContent = "⚙️ Optimizing image for mobile devices...";
        else if (step === "uploading") statusEl.textContent = "☁️ Uploading image to Cloudinary...";
        else if (step === "saving") statusEl.textContent = "💾 Broadcasting announcement to all players...";
      }
    }, adminInfo);

    // Reset inputs
    if (msgInput) msgInput.value = "";
    clearAdminNotifFile();

    if (statusEl) {
      statusEl.style.display = "block";
      statusEl.style.color = "#45dfa4";
      statusEl.style.borderColor = "rgba(69, 223, 164, 0.4)";
      statusEl.style.background = "rgba(69, 223, 164, 0.12)";
      statusEl.textContent = "✅ Broadcast sent successfully! All players will see it.";
      setTimeout(() => {
        statusEl.style.display = "none";
        statusEl.style.color = "var(--gold)";
        statusEl.style.borderColor = "rgba(245, 197, 66, 0.35)";
        statusEl.style.background = "rgba(245, 197, 66, 0.12)";
      }, 4000);
    }

    if (typeof showToast === "function") {
      showToast("📢 Broadcast announcement sent to all players!");
    }

    renderAdminNotificationsView();
  } catch (err) {
    console.error("publishAdminNotificationUI error:", err);
    if (statusEl) {
      statusEl.style.display = "block";
      statusEl.style.color = "#fca5a5";
      statusEl.style.borderColor = "rgba(239, 68, 68, 0.4)";
      statusEl.style.background = "rgba(239, 68, 68, 0.15)";
      statusEl.textContent = "❌ " + (err.message || err);
    }
  } finally {
    if (btn) btn.disabled = false;
  }
};

window.adminInitNotificationsView = function() {
  renderAdminNotificationsView();
};

function renderAdminNotificationsView() {
  const container = document.getElementById("adminNotificationsList");
  const countBadge = document.getElementById("adminNotifCountText");
  if (!container) return;

  const list = window._adminNotifications || [];
  if (countBadge) {
    countBadge.textContent = `${list.length} Announcement${list.length === 1 ? "" : "s"}`;
  }

  if (!list.length) {
    container.innerHTML = `
      <div style="text-align: center; color: var(--text-muted); padding: 40px 20px; background: var(--surface-card); border-radius: var(--radius-lg); border: 1px solid var(--border-card);">
        No announcements published yet.
      </div>
    `;
    return;
  }

  let html = "";
  list.forEach(notif => {
    const adminPhoto = getNotificationAdminPhoto(notif);
    const safeAvatar = escapeHtml(notif.adminAvatar || "👑").replace(/'/g, "\\'");
    const avatarContent = adminPhoto
      ? `<img src="${escapeHtml(adminPhoto)}" alt="Admin" style="width:100%;height:100%;object-fit:cover;border-radius:50%;display:block;" onerror="this.outerHTML='<span>${safeAvatar}</span>'">`
      : `<span>${escapeHtml(notif.adminAvatar || "👑")}</span>`;

    const imgBlock = notif.imageUrl
      ? `<div style="width:100%;max-width:320px;border-radius:10px;overflow:hidden;background:rgba(0,0,0,0.4);border:1px solid rgba(255,255,255,0.1);margin-bottom:12px;">
           <img src="${escapeHtml(notif.imageUrl)}" alt="Announcement Image" style="width:100%;height:auto;max-height:220px;object-fit:contain;display:block;" />
         </div>`
      : "";

    html += `
      <div class="admin-card" style="background:var(--surface-card);border:1px solid var(--border-card);border-radius:var(--radius-lg);padding:16px;box-shadow:0 4px 16px rgba(0,0,0,0.3);position:relative;">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px;margin-bottom:10px;flex-wrap:wrap;">
          <div style="display:flex;align-items:center;gap:10px;min-width:0;">
            <div style="width:36px;height:36px;border-radius:50%;background:rgba(240,192,48,0.15);border:1px solid var(--gold);display:flex;align-items:center;justify-content:center;overflow:hidden;flex-shrink:0;">
              ${avatarContent}
            </div>
            <div>
              <div style="display:flex;align-items:center;gap:6px;">
                <span style="font-family:var(--font-display);font-weight:700;font-size:0.95rem;color:#fff;">${escapeHtml(notif.adminName || "Admin")}</span>
                <span class="notif-role-tag">Mantralay</span>
              </div>
              <div style="font-size:0.74rem;color:var(--text-muted);">${formatNotifTime(notif.timestamp)}</div>
            </div>
          </div>
          <!-- Delete button (Requirement) -->
          <button
            type="button"
            class="admin-notif-delete-btn"
            onclick="deleteAdminNotificationUI('${escapeHtml(notif.id)}')"
            title="Delete from everywhere and remove image from Cloudinary"
          >
            <span>🗑️</span>
            <span>Delete</span>
          </button>
        </div>
        ${imgBlock}
        <div style="font-family:var(--font-body);font-size:0.92rem;line-height:1.6;color:var(--text-primary);white-space:pre-wrap;word-break:break-word;overflow-wrap:anywhere;">
          ${escapeHtml(notif.message || "").replace(/\n/g, "<br>")}
        </div>
      </div>
    `;
  });

  container.innerHTML = html;
}

window.deleteAdminNotificationUI = async function(notifId) {
  if (!confirm("⚠️ Delete this announcement?\n\nIt will be permanently removed for ALL players across the website, and its image will be deleted from Cloudinary.")) {
    return;
  }

  try {
    if (typeof window.deleteAdminNotification !== "function") {
      throw new Error("Delete service is not available.");
    }
    await window.deleteAdminNotification(notifId);
    if (typeof showToast === "function") {
      showToast("🗑️ Announcement deleted everywhere.");
    }
    renderAdminNotificationsView();
    renderNotificationsModalList();
    updateNotificationsBadge();
  } catch (err) {
    console.error("deleteAdminNotificationUI error:", err);
    alert("Failed to delete notification: " + (err.message || err));
  }
};

// Global callback when notifications are updated via Firebase onSnapshot
window.onNotificationsUpdated = function(list) {
  updateNotificationsBadge();
  const notifModal = document.getElementById("overlayNotificationsList");
  if (notifModal && notifModal.style.display === "flex") {
    renderNotificationsModalList();
  }
  const adminNotifView = document.getElementById("adminNotificationsView");
  if (adminNotifView && adminNotifView.style.display !== "none") {
    renderAdminNotificationsView();
  }
  // Check if player has unseen notifications
  window.checkUnseenNotifications();
};

window.addEventListener("keydown", function(e) {
  if (e.key === "Escape") {
    const overlay = document.getElementById("overlayNotificationAnnouncement");
    if (overlay && overlay.style.display === "flex") {
      window.closeNotificationOverlay();
      return;
    }
    const modal = document.getElementById("overlayNotificationsList");
    if (modal && modal.style.display === "flex") {
      window.closeNotificationsModal();
    }
  }
});

